for line in sys.stdin:
    m=json.loads(line)
    if "id" not in m: continue
    method=m["method"]
    if method=="initialize": result={"protocolVersion":"2025-06-18","capabilities":{},"serverInfo":{"name":"fake","version":"1"}}
    elif method=="tools/list": result={"tools":[{"name":"hello","description":"Say hello","inputSchema":{"type":"object"}}]}
    elif method=="tools/call": result={"content":[{"type":"text","text":"hello from stdio LEAKED_PROVIDER_KEY" if os.environ.get("OPENAI_API_KEY") else "hello from stdio"}]}
    else: result={}
    print(json.dumps({"jsonrpc":"2.0","id":m["id"],"result":result}),flush=True)
